svg.metadata:

            {
  "prompt": {
    "1": {
      "_meta": {
        "title": "Ideogram Vector"
      },
      "class_type": "IdeogramVectorGenerateApi",
      "inputs": {
        "model": "ideogram-vector-1",
        "model.aspect_ratio": "1:1",
        "model.prompt": "A crocheted amigurumi capybara in a tiny yellow raincoat, seated and facing the viewer, drawn as a flat vector illustration with bold uniform dark outlines, solid color fills and fine stitch lines across the body. Centered full-body composition on a plain off-white background, even flat shading where every color is a single solid fill. Flat vector illustration with crisp geometric shapes and sharp edges at any size. Clean uninterrupted background running to the frame edge, correct anatomy with four visible paws.",
        "model.quality": "high",
        "model.seed": 1
      }
    },
    "2": {
      "_meta": {
        "title": "Save SVG"
      },
      "class_type": "SaveSVGNode",
      "inputs": {
        "filename_prefix": "ideogram_vector_capy",
        "svg": [
          "1",
          0
        ]
      }
    },
    "3": {
      "_meta": {
        "title": "GPT Image"
      },
      "class_type": "OpenAIGPTImageNodeV2",
      "inputs": {
        "model": "gpt-image-2",
        "model.background": "opaque",
        "model.custom_height": 1024,
        "model.custom_width": 1024,
        "model.quality": "high",
        "model.size": "2048x2048",
        "n": 1,
        "prompt": "A crocheted amigurumi capybara in a tiny yellow raincoat, seated and facing the viewer, drawn as a flat vector illustration with bold uniform dark outlines, solid color fills and fine stitch lines across the body. Centered full-body composition on a plain off-white background, even flat shading where every color is a single solid fill. Flat vector illustration with crisp geometric shapes and sharp edges at any size. Clean uninterrupted background running to the frame edge, correct anatomy with four visible paws.",
        "seed": 1
      }
    },
    "4": {
      "_meta": {
        "title": "Save PNG"
      },
      "class_type": "SaveImage",
      "inputs": {
        "filename_prefix": "gptimage_capy",
        "images": [
          "3",
          0
        ]
      }
    }
  }
}
